-- GiysiGO PostgreSQL reference schema (MVP).
-- Apply to an empty PostgreSQL database. UUID values are generated by the .NET application.
-- EF Core migrations should reproduce this schema per module; do not apply both this file
-- and migrations to the same database. Money is TRY in MVP.

BEGIN;

CREATE SCHEMA identity;
CREATE SCHEMA catalog;
CREATE SCHEMA ordering;
CREATE SCHEMA operations;
CREATE SCHEMA building_blocks;

-- Identity: accounts, tenant-scoped access, and customer addresses.
CREATE TABLE identity.users (
    id uuid PRIMARY KEY,
    email text NOT NULL,
    password_hash text NOT NULL,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (length(trim(email)) > 3)
);
CREATE UNIQUE INDEX ux_users_email_ci ON identity.users (lower(email));

CREATE TABLE identity.roles (
    id uuid PRIMARY KEY,
    code text NOT NULL UNIQUE,
    name text NOT NULL,
    scope text NOT NULL CHECK (scope IN ('GLOBAL', 'CORPORATE', 'STORE')),
    is_active boolean NOT NULL DEFAULT true,
    UNIQUE (id, scope)
);

CREATE TABLE identity.permissions (
    id uuid PRIMARY KEY,
    code text NOT NULL UNIQUE,
    description text NOT NULL,
    is_active boolean NOT NULL DEFAULT true
);

CREATE TABLE identity.role_permissions (
    role_id uuid NOT NULL REFERENCES identity.roles(id),
    permission_id uuid NOT NULL REFERENCES identity.permissions(id),
    PRIMARY KEY (role_id, permission_id)
);

CREATE TABLE identity.user_roles (
    user_id uuid NOT NULL REFERENCES identity.users(id),
    role_id uuid NOT NULL,
    role_scope text NOT NULL DEFAULT 'GLOBAL' CHECK (role_scope = 'GLOBAL'),
    PRIMARY KEY (user_id, role_id),
    FOREIGN KEY (role_id, role_scope) REFERENCES identity.roles(id, scope)
);

CREATE TABLE identity.corporates (
    id uuid PRIMARY KEY,
    name text NOT NULL,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE identity.corporate_memberships (
    user_id uuid NOT NULL REFERENCES identity.users(id),
    corporate_id uuid NOT NULL REFERENCES identity.corporates(id),
    role_id uuid NOT NULL,
    role_scope text NOT NULL DEFAULT 'CORPORATE' CHECK (role_scope = 'CORPORATE'),
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, corporate_id, role_id),
    FOREIGN KEY (role_id, role_scope) REFERENCES identity.roles(id, scope)
);
CREATE INDEX ix_corporate_memberships_corporate ON identity.corporate_memberships (corporate_id) WHERE is_active;

CREATE TABLE identity.customer_addresses (
    id uuid PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES identity.users(id),
    label text NOT NULL,
    address_text text NOT NULL,
    latitude numeric(9,6) NOT NULL CHECK (latitude BETWEEN -90 AND 90),
    longitude numeric(9,6) NOT NULL CHECK (longitude BETWEEN -180 AND 180),
    contact_name text NOT NULL,
    contact_phone text NOT NULL,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_customer_addresses_user ON identity.customer_addresses (user_id) WHERE is_active;

-- Catalog: only the platform manages product types and services. Stores enable offerings.
CREATE TABLE catalog.stores (
    id uuid PRIMARY KEY,
    corporate_id uuid NOT NULL REFERENCES identity.corporates(id),
    name text NOT NULL,
    address_text text NOT NULL,
    latitude numeric(9,6) NOT NULL CHECK (latitude BETWEEN -90 AND 90),
    longitude numeric(9,6) NOT NULL CHECK (longitude BETWEEN -180 AND 180),
    service_radius_km numeric(7,2) NOT NULL CHECK (service_radius_km > 0),
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_stores_corporate ON catalog.stores (corporate_id) WHERE is_active;

CREATE TABLE identity.store_assignments (
    user_id uuid NOT NULL REFERENCES identity.users(id),
    store_id uuid NOT NULL REFERENCES catalog.stores(id),
    role_id uuid NOT NULL,
    role_scope text NOT NULL DEFAULT 'STORE' CHECK (role_scope = 'STORE'),
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, store_id, role_id),
    FOREIGN KEY (role_id, role_scope) REFERENCES identity.roles(id, scope)
);
CREATE INDEX ix_store_assignments_store ON identity.store_assignments (store_id) WHERE is_active;

CREATE TABLE catalog.product_categories (
    id uuid PRIMARY KEY,
    code text NOT NULL UNIQUE,
    name text NOT NULL,
    sort_order integer NOT NULL DEFAULT 0,
    is_active boolean NOT NULL DEFAULT true
);

CREATE TABLE catalog.product_types (
    id uuid PRIMARY KEY,
    category_id uuid NOT NULL REFERENCES catalog.product_categories(id),
    code text NOT NULL UNIQUE,
    name text NOT NULL,
    base_unit text NOT NULL CHECK (base_unit IN ('PIECE', 'M2')),
    is_active boolean NOT NULL DEFAULT true
);
CREATE INDEX ix_product_types_category ON catalog.product_types (category_id) WHERE is_active;

CREATE TABLE catalog.services (
    id uuid PRIMARY KEY,
    code text NOT NULL UNIQUE,
    name text NOT NULL,
    is_active boolean NOT NULL DEFAULT true
);

CREATE TABLE catalog.product_type_services (
    id uuid PRIMARY KEY,
    product_type_id uuid NOT NULL REFERENCES catalog.product_types(id),
    service_id uuid NOT NULL REFERENCES catalog.services(id),
    default_price numeric(12,2) NOT NULL CHECK (default_price >= 0),
    currency char(3) NOT NULL DEFAULT 'TRY' CHECK (currency = 'TRY'),
    price_unit text NOT NULL CHECK (price_unit IN ('PIECE', 'M2')),
    selection_kind text NOT NULL CHECK (selection_kind IN ('BASE', 'ALTERNATIVE', 'ADD_ON')),
    is_default_selected boolean NOT NULL DEFAULT false,
    is_active boolean NOT NULL DEFAULT true,
    UNIQUE (product_type_id, service_id),
    UNIQUE (id, product_type_id)
);
CREATE UNIQUE INDEX ux_product_type_services_default
    ON catalog.product_type_services (product_type_id) WHERE is_default_selected;
CREATE INDEX ix_product_type_services_service ON catalog.product_type_services (service_id) WHERE is_active;

CREATE TABLE catalog.store_offerings (
    id uuid PRIMARY KEY,
    store_id uuid NOT NULL REFERENCES catalog.stores(id),
    product_type_service_id uuid NOT NULL REFERENCES catalog.product_type_services(id),
    price_override numeric(12,2) CHECK (price_override >= 0),
    is_active boolean NOT NULL DEFAULT true,
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (store_id, product_type_service_id),
    UNIQUE (id, store_id)
);
CREATE INDEX ix_store_offerings_service ON catalog.store_offerings (product_type_service_id) WHERE is_active;

-- Ordering: one cart/order belongs to one customer and one store.
CREATE TABLE ordering.carts (
    id uuid PRIMARY KEY,
    customer_id uuid NOT NULL REFERENCES identity.users(id),
    store_id uuid NOT NULL REFERENCES catalog.stores(id),
    address_id uuid NOT NULL REFERENCES identity.customer_addresses(id),
    pickup_window_start timestamptz,
    pickup_window_end timestamptz,
    status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN', 'CHECKED_OUT', 'ABANDONED')),
    version integer NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK ((pickup_window_start IS NULL AND pickup_window_end IS NULL)
        OR (pickup_window_start IS NOT NULL AND pickup_window_end > pickup_window_start)),
    UNIQUE (id, store_id)
);
CREATE UNIQUE INDEX ux_carts_one_open_per_customer_store
    ON ordering.carts (customer_id, store_id) WHERE status = 'OPEN';

CREATE TABLE ordering.cart_items (
    id uuid PRIMARY KEY,
    cart_id uuid NOT NULL REFERENCES ordering.carts(id) ON DELETE CASCADE,
    product_type_id uuid NOT NULL REFERENCES catalog.product_types(id),
    customer_note text,
    customer_measurement numeric(12,3) CHECK (customer_measurement > 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (id, product_type_id)
);
CREATE INDEX ix_cart_items_cart ON ordering.cart_items (cart_id);

CREATE TABLE ordering.cart_item_services (
    cart_item_id uuid NOT NULL REFERENCES ordering.cart_items(id) ON DELETE CASCADE,
    store_offering_id uuid NOT NULL REFERENCES catalog.store_offerings(id),
    PRIMARY KEY (cart_item_id, store_offering_id)
);

CREATE TABLE ordering.cart_item_photos (
    id uuid PRIMARY KEY,
    cart_item_id uuid NOT NULL REFERENCES ordering.cart_items(id) ON DELETE CASCADE,
    storage_key text NOT NULL,
    photo_type text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_cart_item_photos_item ON ordering.cart_item_photos (cart_item_id);

CREATE TABLE ordering.orders (
    id uuid PRIMARY KEY,
    source_cart_id uuid NOT NULL UNIQUE REFERENCES ordering.carts(id),
    customer_id uuid NOT NULL REFERENCES identity.users(id),
    store_id uuid NOT NULL REFERENCES catalog.stores(id),
    pickup_window_start timestamptz NOT NULL,
    pickup_window_end timestamptz NOT NULL,
    status text NOT NULL DEFAULT 'AWAITING_PICKUP_ASSIGNMENT' CHECK (status IN (
        'AWAITING_PICKUP_ASSIGNMENT', 'PICKUP_ASSIGNED', 'PICKED_UP', 'AT_STORE',
        'INSPECTING', 'AWAITING_STORE_APPROVAL', 'AWAITING_CUSTOMER_APPROVAL',
        'AWAITING_PAYMENT', 'PROCESSING', 'READY_FOR_DELIVERY', 'DELIVERY_ASSIGNED',
        'OUT_FOR_DELIVERY', 'DELIVERED', 'RETURN_REQUESTED', 'RETURN_ASSIGNED',
        'RETURN_IN_TRANSIT', 'RETURNED', 'CANCELLED')),
    estimated_total numeric(12,2) NOT NULL CHECK (estimated_total >= 0),
    currency char(3) NOT NULL DEFAULT 'TRY' CHECK (currency = 'TRY'),
    idempotency_key text NOT NULL,
    version integer NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (pickup_window_end > pickup_window_start),
    UNIQUE (customer_id, idempotency_key)
);
CREATE INDEX ix_orders_store_status ON ordering.orders (store_id, status, created_at DESC);
CREATE INDEX ix_orders_customer ON ordering.orders (customer_id, created_at DESC);

CREATE TABLE ordering.order_address_snapshots (
    order_id uuid PRIMARY KEY REFERENCES ordering.orders(id),
    address_text text NOT NULL,
    latitude numeric(9,6) NOT NULL CHECK (latitude BETWEEN -90 AND 90),
    longitude numeric(9,6) NOT NULL CHECK (longitude BETWEEN -180 AND 180),
    contact_name text NOT NULL,
    contact_phone text NOT NULL
);

CREATE TABLE ordering.order_items (
    id uuid PRIMARY KEY,
    order_id uuid NOT NULL REFERENCES ordering.orders(id),
    product_type_id uuid NOT NULL REFERENCES catalog.product_types(id),
    product_type_name_snapshot text NOT NULL,
    customer_note text,
    customer_measurement numeric(12,3) CHECK (customer_measurement > 0),
    verified_measurement numeric(12,3) CHECK (verified_measurement > 0),
    tracking_code text NOT NULL UNIQUE,
    inspection_status text NOT NULL DEFAULT 'PENDING' CHECK (inspection_status IN ('PENDING', 'ACCEPTED', 'REJECTED')),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (id, product_type_id)
);
CREATE INDEX ix_order_items_order ON ordering.order_items (order_id);

CREATE TABLE ordering.order_item_services (
    id uuid PRIMARY KEY,
    order_item_id uuid NOT NULL REFERENCES ordering.order_items(id),
    product_type_service_id uuid NOT NULL REFERENCES catalog.product_type_services(id),
    service_name_snapshot text NOT NULL,
    estimated_unit_price numeric(12,2) NOT NULL CHECK (estimated_unit_price >= 0),
    price_unit_snapshot text NOT NULL CHECK (price_unit_snapshot IN ('PIECE', 'M2')),
    estimated_quantity numeric(12,3) NOT NULL CHECK (estimated_quantity > 0),
    estimated_price numeric(12,2) NOT NULL CHECK (estimated_price >= 0),
    status text NOT NULL DEFAULT 'REQUESTED' CHECK (status IN ('REQUESTED', 'APPROVED', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED')),
    UNIQUE (order_item_id, product_type_service_id)
);
CREATE INDEX ix_order_item_services_item ON ordering.order_item_services (order_item_id);

CREATE TABLE ordering.order_item_photos (
    id uuid PRIMARY KEY,
    order_item_id uuid NOT NULL REFERENCES ordering.order_items(id),
    storage_key text NOT NULL,
    photo_type text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_order_item_photos_item ON ordering.order_item_photos (order_item_id);

CREATE TABLE ordering.price_quotes (
    id uuid PRIMARY KEY,
    order_id uuid NOT NULL REFERENCES ordering.orders(id),
    revision integer NOT NULL CHECK (revision > 0),
    status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN (
        'DRAFT', 'PENDING_STORE_APPROVAL', 'PUBLISHED', 'CUSTOMER_ACCEPTED',
        'CUSTOMER_REJECTED', 'SUPERSEDED', 'EXPIRED')),
    subtotal numeric(12,2) NOT NULL DEFAULT 0 CHECK (subtotal >= 0),
    pickup_fee numeric(12,2) NOT NULL DEFAULT 0 CHECK (pickup_fee >= 0),
    delivery_fee numeric(12,2) NOT NULL DEFAULT 0 CHECK (delivery_fee >= 0),
    total_amount numeric(12,2) NOT NULL CHECK (total_amount >= 0),
    currency char(3) NOT NULL DEFAULT 'TRY' CHECK (currency = 'TRY'),
    expires_at timestamptz,
    customer_decision_by uuid REFERENCES identity.users(id),
    customer_decision_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (order_id, revision),
    CHECK ((customer_decision_by IS NULL) = (customer_decision_at IS NULL))
);
CREATE UNIQUE INDEX ux_price_quotes_one_current
    ON ordering.price_quotes (order_id)
    WHERE status IN ('DRAFT', 'PENDING_STORE_APPROVAL', 'PUBLISHED', 'CUSTOMER_ACCEPTED');

CREATE TABLE ordering.price_quote_lines (
    id uuid PRIMARY KEY,
    price_quote_id uuid NOT NULL REFERENCES ordering.price_quotes(id),
    order_item_service_id uuid NOT NULL REFERENCES ordering.order_item_services(id),
    service_name_snapshot text NOT NULL,
    unit_price numeric(12,2) NOT NULL CHECK (unit_price >= 0),
    price_unit text NOT NULL CHECK (price_unit IN ('PIECE', 'M2')),
    quantity numeric(12,3) NOT NULL CHECK (quantity > 0),
    amount numeric(12,2) NOT NULL CHECK (amount >= 0),
    explanation text,
    UNIQUE (price_quote_id, order_item_service_id)
);
CREATE INDEX ix_price_quote_lines_quote ON ordering.price_quote_lines (price_quote_id);

CREATE TABLE ordering.quote_approval_history (
    id uuid PRIMARY KEY,
    price_quote_id uuid NOT NULL REFERENCES ordering.price_quotes(id),
    action text NOT NULL CHECK (action IN ('SUBMITTED', 'APPROVED', 'REJECTED', 'PUBLISHED')),
    actor_user_id uuid NOT NULL REFERENCES identity.users(id),
    reason text,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_quote_approval_history_quote ON ordering.quote_approval_history (price_quote_id, created_at);

CREATE TABLE ordering.payment_attempts (
    id uuid PRIMARY KEY,
    order_id uuid NOT NULL REFERENCES ordering.orders(id),
    price_quote_id uuid NOT NULL REFERENCES ordering.price_quotes(id),
    provider text NOT NULL,
    provider_payment_id text,
    idempotency_key text NOT NULL,
    amount numeric(12,2) NOT NULL CHECK (amount >= 0),
    currency char(3) NOT NULL DEFAULT 'TRY' CHECK (currency = 'TRY'),
    status text NOT NULL DEFAULT 'INITIATED' CHECK (status IN ('INITIATED', 'SUCCEEDED', 'FAILED', 'CANCELLED')),
    created_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    UNIQUE (provider, idempotency_key)
);
CREATE UNIQUE INDEX ux_payment_attempt_provider_id
    ON ordering.payment_attempts (provider, provider_payment_id)
    WHERE provider_payment_id IS NOT NULL;
CREATE UNIQUE INDEX ux_payment_one_success_per_order
    ON ordering.payment_attempts (order_id) WHERE status = 'SUCCEEDED';
CREATE INDEX ix_payment_attempts_order ON ordering.payment_attempts (order_id, created_at DESC);

CREATE TABLE ordering.order_status_history (
    id uuid PRIMARY KEY,
    order_id uuid NOT NULL REFERENCES ordering.orders(id),
    from_status text,
    to_status text NOT NULL,
    actor_user_id uuid REFERENCES identity.users(id),
    source text NOT NULL CHECK (source IN ('CUSTOMER', 'STORE', 'SYSTEM', 'MOCK_COURIER', 'PAYMENT_PROVIDER')),
    note text,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_order_status_history_order ON ordering.order_status_history (order_id, created_at);

-- Operations: assignments are real decisions; mock couriers generate only test/demo events.
CREATE TABLE operations.courier_profiles (
    id uuid PRIMARY KEY,
    user_id uuid UNIQUE REFERENCES identity.users(id),
    display_name text NOT NULL,
    is_mock boolean NOT NULL DEFAULT false,
    is_active boolean NOT NULL DEFAULT true,
    vehicle_type text NOT NULL,
    capacity_units integer NOT NULL CHECK (capacity_units > 0),
    latitude numeric(9,6) NOT NULL CHECK (latitude BETWEEN -90 AND 90),
    longitude numeric(9,6) NOT NULL CHECK (longitude BETWEEN -180 AND 180),
    max_task_radius_km numeric(7,2) NOT NULL CHECK (max_task_radius_km > 0),
    CHECK ((is_mock AND user_id IS NULL) OR (NOT is_mock AND user_id IS NOT NULL))
);

CREATE TABLE operations.courier_availability (
    id uuid PRIMARY KEY,
    courier_id uuid NOT NULL REFERENCES operations.courier_profiles(id),
    starts_at timestamptz NOT NULL,
    ends_at timestamptz NOT NULL,
    status text NOT NULL CHECK (status IN ('AVAILABLE', 'UNAVAILABLE')),
    CHECK (ends_at > starts_at)
);
CREATE INDEX ix_courier_availability_courier_time
    ON operations.courier_availability (courier_id, starts_at, ends_at);

CREATE TABLE operations.delivery_tasks (
    id uuid PRIMARY KEY,
    order_id uuid NOT NULL REFERENCES ordering.orders(id),
    task_type text NOT NULL CHECK (task_type IN ('CUSTOMER_PICKUP', 'CUSTOMER_DELIVERY', 'REJECTED_ORDER_RETURN')),
    status text NOT NULL DEFAULT 'PENDING_ASSIGNMENT' CHECK (status IN (
        'PENDING_ASSIGNMENT', 'ASSIGNED', 'IN_TRANSIT', 'COMPLETED', 'CANCELLED')),
    origin_address_snapshot text NOT NULL,
    origin_latitude numeric(9,6) NOT NULL CHECK (origin_latitude BETWEEN -90 AND 90),
    origin_longitude numeric(9,6) NOT NULL CHECK (origin_longitude BETWEEN -180 AND 180),
    destination_address_snapshot text NOT NULL,
    destination_latitude numeric(9,6) NOT NULL CHECK (destination_latitude BETWEEN -90 AND 90),
    destination_longitude numeric(9,6) NOT NULL CHECK (destination_longitude BETWEEN -180 AND 180),
    requested_window_start timestamptz NOT NULL,
    requested_window_end timestamptz NOT NULL,
    required_capacity_units integer NOT NULL CHECK (required_capacity_units > 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    CHECK (requested_window_end > requested_window_start)
);
CREATE UNIQUE INDEX ux_delivery_tasks_one_open_type_per_order
    ON operations.delivery_tasks (order_id, task_type)
    WHERE status IN ('PENDING_ASSIGNMENT', 'ASSIGNED', 'IN_TRANSIT');
CREATE INDEX ix_delivery_tasks_pending ON operations.delivery_tasks (requested_window_start)
    WHERE status = 'PENDING_ASSIGNMENT';

CREATE TABLE operations.delivery_assignments (
    id uuid PRIMARY KEY,
    delivery_task_id uuid NOT NULL REFERENCES operations.delivery_tasks(id),
    courier_id uuid NOT NULL REFERENCES operations.courier_profiles(id),
    status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'COMPLETED', 'CANCELLED')),
    assigned_at timestamptz NOT NULL DEFAULT now(),
    unassigned_at timestamptz,
    assignment_reason text NOT NULL,
    distance_km numeric(8,3) NOT NULL CHECK (distance_km >= 0),
    CHECK ((status = 'ACTIVE' AND unassigned_at IS NULL)
        OR (status <> 'ACTIVE' AND unassigned_at IS NOT NULL))
);
CREATE UNIQUE INDEX ux_delivery_assignments_one_active_per_task
    ON operations.delivery_assignments (delivery_task_id) WHERE status = 'ACTIVE';
CREATE INDEX ix_delivery_assignments_courier_active
    ON operations.delivery_assignments (courier_id) WHERE status = 'ACTIVE';

CREATE TABLE operations.delivery_events (
    id uuid PRIMARY KEY,
    delivery_task_id uuid NOT NULL REFERENCES operations.delivery_tasks(id),
    event_type text NOT NULL CHECK (event_type IN (
        'ASSIGNED', 'PICKED_UP', 'AT_STORE', 'OUT_FOR_DELIVERY', 'DELIVERED',
        'RETURN_IN_TRANSIT', 'RETURNED', 'CANCELLED')),
    source text NOT NULL CHECK (source IN ('MOCK', 'COURIER', 'STORE', 'SYSTEM')),
    actor_user_id uuid REFERENCES identity.users(id),
    occurred_at timestamptz NOT NULL DEFAULT now(),
    note text
);
CREATE INDEX ix_delivery_events_task ON operations.delivery_events (delivery_task_id, occurred_at);

CREATE TABLE operations.item_inspections (
    id uuid PRIMARY KEY,
    order_item_id uuid NOT NULL UNIQUE REFERENCES ordering.order_items(id),
    status text NOT NULL CHECK (status IN ('ACCEPTED', 'REJECTED')),
    findings text,
    inspected_by uuid NOT NULL REFERENCES identity.users(id),
    inspected_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE operations.inspection_photos (
    id uuid PRIMARY KEY,
    inspection_id uuid NOT NULL REFERENCES operations.item_inspections(id),
    storage_key text NOT NULL,
    photo_type text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_inspection_photos_inspection ON operations.inspection_photos (inspection_id);

CREATE TABLE operations.item_work (
    id uuid PRIMARY KEY,
    order_item_service_id uuid NOT NULL UNIQUE REFERENCES ordering.order_item_services(id),
    status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'IN_PROGRESS', 'COMPLETED', 'FAILED')),
    started_at timestamptz,
    completed_at timestamptz,
    CHECK (completed_at IS NULL OR started_at IS NOT NULL)
);

CREATE TABLE operations.item_work_history (
    id uuid PRIMARY KEY,
    item_work_id uuid NOT NULL REFERENCES operations.item_work(id),
    from_status text,
    to_status text NOT NULL,
    actor_user_id uuid REFERENCES identity.users(id),
    note text,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_item_work_history_work ON operations.item_work_history (item_work_id, created_at);

-- Transactional outbox for in-process integration events and reliable retries.
CREATE TABLE building_blocks.outbox_messages (
    id uuid PRIMARY KEY,
    event_type text NOT NULL,
    aggregate_id uuid NOT NULL,
    payload jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    processed_at timestamptz,
    attempt_count integer NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    last_error text
);
CREATE INDEX ix_outbox_unprocessed ON building_blocks.outbox_messages (created_at)
    WHERE processed_at IS NULL;

COMMIT;
